function modal(title,content,foot=''){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modalBack"><section class="modal"><header class="modal-head"><h2>${title}</h2><button class="btn ghost" id="closeModal">×</button></header><div class="modal-content">${content}</div>${foot?`<div style="padding:0 22px 22px">${foot}</div>`:''}</section></div>`);$('#closeModal').onclick=()=>$('#modalBack').remove()}
function showCreate(){modal('Your driver, your story',`<div class="eyebrow" style="margin-bottom:18px">STEP 01 / CREATE YOUR ROOKIE</div><div class="form"><label>DRIVER NAME</label><input id="driverName" maxlength="22" placeholder="e.g. Alex Morgan" value="Alex Morgan"><label style="margin-top:8px">NATIONALITY</label><select id="nationality"><option>United Kingdom</option><option>Italy</option><option>France</option><option>Germany</option><option>Brazil</option><option>Japan</option><option>United States</option><option>Australia</option><option>Spain</option><option>Canada</option></select></div><p style="font-size:11px;color:#a6b0ac;line-height:1.6;margin:18px 0 0">Teams will assess your talent and offer you a seat. Your starting team is determined by their interest—not your preference.</p>`,`<button class="btn" id="evaluate">Let the teams evaluate me →</button>`);$('#evaluate').onclick=()=>{let name=$('#driverName').value.trim()||'Alex Morgan';let nationality=$('#nationality').value;$('#modalBack').remove();showOffers(name,nationality)}}
function showOffers(name,nationality){let attrs={};ATTRS.forEach(a=>attrs[a]=rnd(a==='mistakes'?38:49,a==='mistakes'?66:76));let average=Math.round(ATTRS.reduce((n,k)=>n+attrs[k],0)/ATTRS.length);let pool=[9,7,6,4,0].sort((a,b)=>{let av=TEAMS[a].car.speed+TEAMS[a].car.corner;let bv=TEAMS[b].car.speed+TEAMS[b].car.corner;return av-bv}).slice(0,3);let offers=pool.map((ti,i)=>({ti,interest:clamp(72-i*16+rnd(-5,8)+(average-62),40,92)}));window.pendingDriver={name,nationality,attrs,average,offers};modal('Three teams want a word',`<div class="eyebrow" style="margin-bottom:14px">ROOKIE ASSESSMENT / ${name.toUpperCase()}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">${offers.map((o,i)=>{let t=TEAMS[o.ti];return `<div class="contract-card ${i===0?'selected':''}"><div class="teamstripe" style="background:${t.color}"></div><span class="eyebrow">${i===0?'FIRST OFFER':i===1?'ALTERNATIVE':'WILDCARD'}</span><h3>${t.name}</h3><div class="rating">TEAM INTEREST ${o.interest}%</div><p>${i===0?'A chance to learn and prove your worth.':'A competitive seat with something to prove.'}<br>Car strength: ${Math.round((t.car.speed+t.car.corner+t.car.reliability)/3)} / 100</p><div style="font:9px 'DM Mono';color:#899691">${i===0?'EXPECTED: BACK OF GRID':i===1?'EXPECTED: MIDFIELD':'EXPECTED: LOWER MIDFIELD'}</div></div>`}).join('')}</div><div class="stats-row" style="margin-top:14px">${[['PACE','pace'],['QUALIFYING','qualifying'],['CONSISTENCY','consistency'],['WET','wet']].map(([l,k])=>`<div class="statbox"><label>${l}</label><strong>${attrs[k]}</strong></div>`).join('')}</div><p style="font-size:10px;color:#94a19d;line-height:1.6">Driver skill is independent of car performance. Each attribute can matter on race day.</p>`,`<button class="btn" id="acceptOffer">Sign with ${TEAMS[offers[0].ti].name} →</button> <span style="font:10px 'DM Mono';color:#87938f;margin-left:10px">No seat picking. Prove them right.</span>`);$('#acceptOffer').onclick=()=>{let data=window.pendingDriver,o=data.offers[0],teammate=state.drivers.find(d=>d.team===o.ti);let player={name:data.name,nationality:data.nationality,team:o.ti,age:21,rating:data.average,experience:0,points:0,wins:0,podiums:0,retired:false,rep:18,attrs:data.attrs};state.player=player;state.drivers.push(player);if(teammate){/* rookies take an existing seat, veteran moves to reserve */teammate.team=TEAMS.findIndex((_,i)=>!state.drivers.some(d=>d.team===i&&d!==player));if(teammate.team<0)teammate.team=9;}state.view='home';save();$('#modalBack').remove();render()}}
function showCalendar(){modal('2001 World Championship',`<div class="race-table">${TRACKS.map((t,i)=>`<div class="track-row ${i===state.round?'current':''}"><div class="round">${String(i+1).padStart(2,'0')}</div><div><b>${t[0]}</b><div style="font:9px 'DM Mono';color:#8f9b97;margin-top:3px">${t[1]}</div></div><div style="font:10px 'DM Mono';color:#9ba7a2">${t[2]} KM</div><div style="font:10px 'DM Mono';color:#9ba7a2">${t[3]} LAPS</div></div>`).join('')}</div>`)}
function showStandings(){let rows=[...state.drivers].sort((a,b)=>b.points-a.points);modal('Driver championship',`<div class="race-table">${rows.map((d,i)=>`<div class="track-row ${d.name===state.player.name?'current':''}" style="grid-template-columns:38px 1fr 60px 48px"><div class="round">${String(i+1).padStart(2,'0')}</div><div><b>${d.name}</b><div style="font:9px 'DM Mono';color:${TEAMS[d.team].color};margin-top:3px">${TEAMS[d.team].name}</div></div><div style="font:10px 'DM Mono'">${d.wins} W</div><div style="font-weight:700;text-align:right">${d.points}</div></div>`).join('')}</div>`)}
let race=null,raf=0,keys={};
function startRace(){state.view='race';let p=state.player,track=TRACKS[state.round%12];let other=state.drivers.filter(d=>d!==p);let weather=state.round%5===4?'wet':state.round%7===2?'changeable':'dry';race={track,weather,elapsed:0,dist:0,lap:0,lapLen:1.18,tyre:100,fuel:100,damage:0,speed:0,gear:1,steer:0,playerLane:0,offroad:0,paused:false,cockpit:false,finished:false,opponents:other.map((d,i)=>({driver:d,dist:0,lane:(i%5-2)*.34,pace:100+(d.attrs.pace+TEAMS[d.team].car.speed-135)*.28+rnd(-4,4),retired:false,disturb:0})),lastLap:0,lapStart:0,flash:'LIGHTS OUT!',flashTime:1.7,weatherTimer:14+Math.random()*18,wetness:weather==='wet'?62:0};render();window.addEventListener('keydown',onKeyDown);window.addEventListener('keyup',onKeyUp);loop(performance.now())}
function onKeyDown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='c'&&race)race.cockpit=!race.cockpit;if(e.key==='Escape'&&race){race.paused=!race.paused;race.flash=race.paused?'PAUSED — PRESS ESC TO RESUME':'';race.flashTime=99}}
function onKeyUp(e){keys[e.key.toLowerCase()]=false}
function renderRace(){let app=$('#app');app.innerHTML=`<div class="race-screen"><header class="race-top"><span><b>GRIDLINE 2001</b>　/　${race.track[0].toUpperCase()}</span><span>${race.weather==='wet'?'RAIN':race.weather==='changeable'?'CHANGEABLE':'CLEAR'} CONDITIONS</span><span>ESC　PAUSE</span></header><div class="race-stage"><canvas id="gameCanvas"></canvas><div class="hud"><div class="hud-panel hud-pos" id="hudPos">20<small>POSITION</small></div><div class="hud-panel hud-timing" id="hudTiming">LAP 1 / 3<br>0:00.00<br>BEST —</div><div class="hud-panel hud-gauge"><div><span class="speed" id="hudSpeed">000</span> <span class="gear" id="hudGear">1</span></div><div><small>KM/H　　GEAR</small></div><div class="tyres" id="hudTyres"><i class="tyre"></i><i class="tyre"></i><i class="tyre"></i><i class="tyre"></i></div><div style="font:9px 'DM Mono';color:#a6b2ac;margin-top:5px">TYRE　<span id="hudWear">100%</span>　FUEL　<span id="hudFuel">100%</span></div></div><div id="hudMessage" class="hud-message">LIGHTS OUT!</div></div><div class="touch-controls"><div class="touch-group"><button data-key="arrowleft">◀</button><button data-key="arrowright">▶</button></div><div class="touch-group"><button data-key="arrowdown">BRAKE</button><button data-key="arrowup">GAS</button></div></div></div><footer class="race-bottom"><span id="raceHint">ARROWS / WASD TO DRIVE　·　C COCKPIT　·　ESC PAUSE</span><span class="controls">SPEED · TYRE WEAR · FUEL · DAMAGE</span><button class="btn ghost" id="quitRace" style="padding:6px 10px;font-size:11px;pointer-events:auto">RETIRE</button></footer></div>`;$('#quitRace').onclick=()=>{if(confirm('Retire from this Grand Prix?'))finishRace(true)};document.querySelectorAll('.touch-controls button').forEach(b=>{let k=b.dataset.key;b.onpointerdown=e=>{e.preventDefault();keys[k]=true};b.onpointerup=b.onpointercancel=b.onpointerleave=()=>keys[k]=false});resizeCanvas()}
function resizeCanvas(){let c=$('#gameCanvas');if(!c)return;let r=c.getBoundingClientRect();c.width=Math.round(r.width*devicePixelRatio);c.height=Math.round(r.height*devicePixelRatio)}
window.addEventListener('resize',()=>{if(state.view==='race')resizeCanvas()});

function curveAt(x){return Math.sin(x*5.1)*.52+Math.sin(x*2.35+1.4)*.27+Math.sin(x*9.4)*.08}
function drawCar(ctx,x,y,s,color,cockpit=false,isPlayer=false){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#11191b';ctx.fillRect(-18,10,9,24);ctx.fillRect(10,10,9,24);ctx.fillRect(-16,-24,8,18);ctx.fillRect(8,-24,8,18);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-29,21);ctx.lineTo(-24,10);ctx.lineTo(-18,-12);ctx.lineTo(-13,-31);ctx.lineTo(-8,-43);ctx.lineTo(8,-43);ctx.lineTo(13,-31);ctx.lineTo(18,-12);ctx.lineTo(24,10);ctx.lineTo(29,21);ctx.lineTo(20,25);ctx.lineTo(10,19);ctx.lineTo(-10,19);ctx.lineTo(-20,25);ctx.closePath();ctx.fill();ctx.fillStyle='#d9ded0';ctx.fillRect(-32,20,64,5);ctx.fillRect(-22,-29,44,4);ctx.fillStyle='#11191b';ctx.beginPath();ctx.ellipse(0,-12,10,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=cockpit?'#8dd4df':'#8faeb0';ctx.beginPath();ctx.ellipse(0,-17,7,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4c4';ctx.fillRect(-22,10,5,3);ctx.fillRect(17,10,5,3);if(isPlayer){ctx.fillStyle='#d8f36a';ctx.fillRect(-2,21,4,3)}ctx.restore()}
function renderWorld(){let c=$('#gameCanvas');if(!c||!race)return;let ctx=c.getContext('2d'),w=c.width,h=c.height,scale=devicePixelRatio;ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,w,h);let horizon=h*.37,wet=race.wetness;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#587a88');sky.addColorStop(1,'#c7c8a9');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon);ctx.fillStyle='#ffe9a8';ctx.beginPath();ctx.arc(w*.79,h*.12,Math.min(w,h)*.044,0,Math.PI*2);ctx.fill();ctx.fillStyle='#768f84';ctx.beginPath();ctx.moveTo(0,horizon*.86);for(let x=0;x<=w;x+=w/8)ctx.lineTo(x,horizon*(.62+Math.sin(x/w*12+race.dist*2)*.14));ctx.lineTo(w,horizon);ctx.lineTo(0,horizon);ctx.fill();ctx.fillStyle='#4b6854';ctx.fillRect(0,horizon,w,h-horizon);
let strips=48;for(let i=0;i<strips;i++){let d0=i/strips,d1=(i+1)/strips,y0=horizon+d0*d0*(h-horizon),y1=horizon+d1*d1*(h-horizon),cent0=w/2+curveAt(race.dist+(1-d0)*.62)*w*.34,cent1=w/2+curveAt(race.dist+(1-d1)*.62)*w*.34,half0=w*(.025+.40*d0),half1=w*(.025+.40*d1),seg=Math.floor((race.dist*35+i)/2)%2;ctx.fillStyle=seg?'#4c7054':'#426449';ctx.fillRect(0,y0,w,y1-y0+1);ctx.fillStyle=seg?'#71805b':'#667e58';ctx.beginPath();ctx.moveTo(cent0-half0*1.22,y0);ctx.lineTo(cent0-half0,y0);ctx.lineTo(cent1-half1,y1);ctx.lineTo(cent1-half1*1.22,y1);ctx.fill();ctx.beginPath();ctx.moveTo(cent0+half0,y0);ctx.lineTo(cent0+half0*1.22,y0);ctx.lineTo(cent1+half1*1.22,y1);ctx.lineTo(cent1+half1,y1);ctx.fill();ctx.fillStyle='#c9c5b2';ctx.beginPath();ctx.moveTo(cent0-half0,y0);ctx.lineTo(cent0+half0,y0);ctx.lineTo(cent1+half1,y1);ctx.lineTo(cent1-half1,y1);ctx.fill();ctx.fillStyle=wet>10?'#6c8583':'#4a5554';ctx.beginPath();ctx.moveTo(cent0-half0*.94,y0);ctx.lineTo(cent0+half0*.94,y0);ctx.lineTo(cent1+half1*.94,y1);ctx.lineTo(cent1-half1*.94,y1);ctx.fill();if(i%2===0){ctx.fillStyle='#f0eee0';ctx.beginPath();ctx.moveTo(cent0-half0*1.13,y0);ctx.lineTo(cent0-half0*.99,y0);ctx.lineTo(cent1-half1*.99,y1);ctx.lineTo(cent1-half1*1.13,y1);ctx.fill();ctx.beginPath();ctx.moveTo(cent0+half0*.99,y0);ctx.lineTo(cent0+half0*1.13,y0);ctx.lineTo(cent1+half1*1.13,y1);ctx.lineTo(cent1+half1*.99,y1);ctx.fill();}if(i%7===0&&d1<.66){let bx=cent1+half1*1.5,by=y1,size=2+12*d1;ctx.fillStyle='#e7e2c9';ctx.fillRect(bx,by-size*2,size*1.2,size*2);ctx.fillStyle='#bf4e40';ctx.fillRect(bx,by-size*2,size*1.2,size*.5);ctx.fillRect(bx+size*.7,by-size*1.2,size*.45,size*1.2);}}
let objects=race.opponents.filter(o=>!o.retired).map(o=>({o,delta:o.dist-race.dist})).filter(v=>v.delta>-.35&&v.delta<.9).sort((a,b)=>a.delta-b.delta);for(let {o,delta} of objects){let depth=clamp(1-delta/.95,.02,.96),y=horizon+depth*depth*(h-horizon)*.91,x=w/2+curveAt(race.dist+delta)*w*.34+o.lane*w*(.025+.40*depth);let s=.14+depth*.8;drawCar(ctx,x,y,s,TEAMS[o.driver.team].color,false)}
let playerX=w/2+race.playerLane*w*.31;let playerY=h*.86;drawCar(ctx,playerX,playerY,scale*(race.cockpit?1.12:1.55),TEAMS[race.player.team].color,race.cockpit,true);if(race.cockpit){ctx.fillStyle='#15191a';ctx.fillRect(0,h*.91,w,h*.09);ctx.fillStyle='#8c9a90';ctx.fillRect(w*.35,h*.85,w*.3,h*.04)}if(wet>5){ctx.fillStyle=`rgba(190,216,220,${Math.min(.18,wet/500)})`;ctx.fillRect(0,0,w,h);for(let i=0;i<18;i++){let x=((i*173+race.elapsed*95)%w),y=((i*79+race.elapsed*170)%h);ctx.fillStyle='#d7e5df55';ctx.fillRect(x,y,1*scale,9*scale)}}if(race.damage>35){ctx.fillStyle=`rgba(200,40,25,${Math.min(.18,(race.damage-35)/500)})`;ctx.fillRect(0,0,w,h)}}
function updateRace(dt){if(!race||race.paused||race.finished)return;race.elapsed+=dt;if(race.flashTime>0){race.flashTime-=dt;if(race.flashTime<=0)race.flash=''}let p=race.player,car=TEAMS[p.team].car,wet=race.wetness;let throttle=keys.arrowup||keys.w||keys[' '],brake=keys.arrowdown||keys.s,steer=(keys.arrowleft||keys.a?-1:0)+(keys.arrowright||keys.d?1:0),curve=curveAt(race.dist+.035);race.steer+=(steer-race.steer)*Math.min(1,dt*4);race.playerLane=clamp(race.playerLane+race.steer*dt*(.83+car.stability/180),-1.08,1.08);let max=153+car.speed*1.42;let acceleration=(throttle?105+car.accel*.36:0)-(brake?165:0)-(throttle?0:12+race.speed*.026);if(race.damage>30)max*=1-(race.damage-30)*.003;if(race.tyre<35)max*=.86;if(wet>15)max*=1-(wet*.0015);race.speed=clamp(race.speed+acceleration*dt,0,max);if(Math.abs(race.playerLane)>0.74){race.speed=Math.max(0,race.speed-dt*42);race.offroad+=dt;if(race.offroad>1.3){race.damage=clamp(race.damage+dt*1.7,0,100);race.flash='OFF TRACK';race.flashTime=.5}}else race.offroad=Math.max(0,race.offroad-dt*2);
let curveLoad=Math.abs(curve)*Math.pow(race.speed/210,2);if(curveLoad>car.stability/100+.23){race.speed=Math.max(30,race.speed-(curveLoad-car.stability/100-.23)*dt*70);if(Math.random()<dt*.18)race.playerLane=clamp(race.playerLane+Math.sign(curve)*.055,-1,1)}if(throttle&&race.speed>50)race.tyre=clamp(race.tyre-dt*(.09+(race.speed/300)*.09+(Math.abs(steer)*.13)+(wet>20?.035:0)),0,100);race.fuel=clamp(race.fuel-dt*(throttle?.11:.045),0,100);if(race.fuel<5)race.speed=Math.min(race.speed,85);race.dist+=race.speed/3600*dt;if(race.dist>=race.lapLen*(race.lap+1)){race.lap++;let lapTime=race.elapsed-race.lapStart;race.lastLap=lapTime;race.lapStart=race.elapsed;race.flash=`LAP ${race.lap} COMPLETE`;race.flashTime=1.4;if(race.lap>=3){finishRace(false);return}}
for(let o of race.opponents){if(o.retired)continue;let target=(o.pace*2.55)/3600;let variation=1+Math.sin(race.elapsed*.35+o.driver.team)*.055;if(wet>30)variation*=.89+(o.driver.attrs.wet/100)*.17;let gap=o.dist-race.dist;if(Math.abs(gap)<.06)variation*=.8+o.driver.attrs.overtaking/400;o.dist+=target*variation*dt;if(Math.random()<dt*(100-TEAMS[o.driver.team].car.reliability)*.000012){o.retired=true;o.driver.retired=true}}
let ordered=race.opponents.filter(o=>!o.retired).sort((a,b)=>b.dist-a.dist);let position=1+ordered.filter(o=>o.dist>race.dist).length;for(let o of ordered){if(Math.abs(o.dist-race.dist)<.016&&Math.abs(o.lane-race.playerLane)<.30){race.damage=clamp(race.damage+dt*9,0,100);race.speed=Math.max(0,race.speed-35*dt);o.dist-=.002;if(race.flashTime<=0){race.flash='CONTACT — DAMAGE';race.flashTime=.8}}}
if(race.elapsed>race.weatherTimer&&race.weather==='changeable'){race.wetness=clamp(race.wetness+(Math.random()<.54?22:-18),0,75);race.weatherTimer+=12+Math.random()*15;race.flash=race.wetness>30?'RAIN ON TRACK':'TRACK DRYING';race.flashTime=1.2}if(race.weather==='wet')race.wetness=62;if(Math.random()<dt*(100-car.reliability)*.000002){race.speed*=.65;race.damage=clamp(race.damage+18,0,100);race.flash='MECHANICAL PROBLEM';race.flashTime=1.5}
race.gear=clamp(Math.floor(race.speed/43)+1,1,7);updateHud(position);}
function updateHud(position){if(!race)return;$('#hudPos').innerHTML=`${String(position).padStart(2,'0')}<small>POSITION</small>`;$('#hudTiming').innerHTML=`LAP ${Math.min(race.lap+1,3)} / 3<br>${timefmt(race.elapsed)}<br>LAST ${race.lastLap?timefmt(race.lastLap):'—'}`;$('#hudSpeed').textContent=String(Math.round(race.speed)).padStart(3,'0');$('#hudGear').textContent=race.gear;$('#hudWear').textContent=`${Math.round(race.tyre)}%`;$('#hudFuel').textContent=`${Math.round(race.fuel)}%`;document.querySelectorAll('.tyre').forEach(el=>{el.className='tyre'+(race.tyre<25?' bad':race.tyre<55?' worn':'')});let m=$('#hudMessage');if(m)m.textContent=race.flash||''}
function timefmt(sec){let m=Math.floor(sec/60),s=(sec%60).toFixed(2).padStart(5,'0');return `${m}:${s}`}
function loop(now){if(!race||state.view!=='race')return;let dt=Math.min(.05,(now-(race.lastNow||now))/1000);race.lastNow=now;updateRace(dt);if(!race)return;renderWorld();raf=requestAnimationFrame(loop)}

