function render(){if(state.view==='race'){renderRace();return}let app=$('#app');app.innerHTML=`<header class="topbar"><div class="brand"><i class="brandmark"></i><span>GRIDLINE <small>2001 / WORLD CHAMPIONSHIP</small></span></div><div class="topright"><span class="optional">${state.player?esc(state.player.name.toUpperCase()):'ROOKIE DRIVER'}</span><span class="season-tag">SEASON ${state.season}</span></div></header><main class="wrap">${state.player?careerPage():homePage()}</main>`;bindMain()}
function modal(title,body){let old=document.querySelector('.modal-back');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="btn ghost close-modal" style="padding:7px 11px">CLOSE ×</button></div><div class="modal-content">${body}</div></div></div>`);document.querySelector('.close-modal').onclick=()=>document.querySelector('.modal-back')?.remove();document.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))e.currentTarget.remove()}}
