function showOffers(){let d=state.prospect;let offers=TEAMS.map((t,i)=>{let average=Object.values(t.car).slice(0,6).reduce((a,b)=>a+b,0)/6;let fit=Math.round(clamp(23+(d.rating-65)*.7+(average-70)*.45+rnd(-14,14),8,96));return{team:i,fit}}).sort((a,b)=>b.fit-a.fit).slice(0,5);state.offers=offers;let cards=offers.map(o=>{let t=TEAMS[o.team];return `<div class="contract-card"><div class="teamstripe" style="background:${t.color}"></div><div class="eyebrow">${o.fit>=68?'RACE SEAT OFFER':o.fit>=45?'DEVELOPMENT CONTRACT':'LONG SHOT'}</div><h3>${t.name}</h3><div class="rating">TEAM FIT ${o.fit}% · CAR OVR ${Math.round(Object.values(t.car).slice(0,6).reduce((a,b)=>a+b,0)/6)}</div><p>${o.fit>=68?'They believe your talent can score points from the outset.':o.fit>=45?'A chance to prove yourself in a competitive midfield car.':'A tough team, but a strong season could change everything.'}</p><button class="btn sign-team" data-team="${o.team}" style="width:100%;background:${t.color};box-shadow:3px 3px 0 #111">SIGN CONTRACT →</button></div>`}).join('');modal('The teams have spoken',`<div class="driver-card" style="margin-bottom:16px"><div class="portrait">${initials(d.name)}</div><div><h3>${esc(d.name)}</h3><p>AGE ${d.age} · OVERALL ${d.rating} · ROOKIE</p></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px">${cards}</div>`);document.querySelectorAll('.sign-team').forEach(b=>b.onclick=()=>signTeam(+b.dataset.team))}
function signTeam(team){let d=state.prospect,drivers=state.drivers.filter(x=>x.team===team).sort((a,b)=>a.rating-b.rating),replaced=drivers[0];Object.assign(d,{team,rep:20});state.drivers=state.drivers.filter(x=>x!==replaced);state.drivers.push(d);replaced.team=-1;state.reserve=replaced;state.player=d;delete state.prospect;delete state.offers;state.view='home';document.querySelector('.modal-back')?.remove();save();render()}
function calendarModal(){modal('2001 Championship calendar',`<div class="race-table">${TRACKS.map((t,i)=>`<div class="track-row ${i===state.round?'current':''}"><div class="round">${String(i+1).padStart(2,'0')}</div><div><b>${t[0]}</b><div style="font:9px 'DM Mono';color:#93a09b;margin-top:3px">${t[1]} · ${t[4]}</div></div><div>${t[2]} KM</div><div>${t[3]} LAPS</div></div>`).join('')}</div>`)}
function showStandings(){let list=[...state.drivers].sort((a,b)=>b.points-a.points);modal('World championship standings',`<table class="standings"><thead><tr><th>POS</th><th>DRIVER</th><th style="text-align:right">PTS</th></tr></thead><tbody>${standingsRows(list)}</tbody></table>`)}
function development(){let p=state.player;if(p.developedSeason===state.season){modal('Development programme',`<p>Your training programme is complete for this season. Keep racing to gain experience and unlock next year's development.</p>`);return}let areas=[['PACE','pace'],['QUALIFYING','qualifying'],['CONSISTENCY','consistency'],['OVERTAKING','overtaking'],['WET WEATHER','wet'],['TYRE MANAGEMENT','tyres']];modal('Driver development',`<p style="color:#aab5b0;font-size:12px">Choose one focus for this season. Your driver grows independently from the car.</p><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">${areas.map(([label,key])=>`<button class="btn secondary develop" data-key="${key}" style="text-align:left">${label} <span style="float:right;color:var(--lime)">${p.attrs[key]}</span></button>`).join('')}</div>`);document.querySelectorAll('.develop').forEach(b=>b.onclick=()=>{let k=b.dataset.key;p.attrs[k]=clamp(p.attrs[k]+rnd(2,5),0,99);p.rating=Math.round(Object.values(p.attrs).reduce((a,v)=>a+v,0)/ATTRS.length);p.developedSeason=state.season;p.rep=(p.rep||18)+2;save();document.querySelector('.modal-back')?.remove();render()})}
function bindMain(){let c=$('#create');if(c)c.onclick=createModal;let r=$('#race');if(r)r.onclick=startRace;let cal=$('#calendar');if(cal)cal.onclick=calendarModal;let sb=$('#standingsBtn');if(sb)sb.onclick=showStandings;let dev=$('#develop');if(dev)dev.onclick=development;let restart=$('#newcareer');if(restart)restart.onclick=()=>{if(confirm('Start a new career? Your current save will be replaced.')){localStorage.removeItem('gridline-save');state=fresh();render()}}}
function startRace(){state.view='race';raceData={running:true,done:false,last:performance.now(),distance:0,speed:0,steer:0,wear:0,fuel:100,damage:0,weather:state.round%5===4?'RAIN':state.round%7===2?'CHANGEABLE':'CLEAR',message:'LIGHTS OUT',messageTime:1.8,lap:1,view:'chase',keys:{},time:0,offTrack:0,collisions:0};render();raceData.last=performance.now();requestAnimationFrame(raceFrame)}
let raceData=null;
function renderRace(){let t=TRACKS[state.round%12];$('#app').innerHTML=`<div class="race-screen"><div class="race-top"><span><b>GRIDLINE 2001</b> · ${esc(t[0].toUpperCase())} · ROUND ${state.round+1}/12</span><span id="raceClock">0:00.0</span><span>${raceData.view==='cockpit'?'COCKPIT':'CHASE'} VIEW <button id="viewToggle" class="btn ghost" style="padding:5px 8px;margin-left:8px">C</button></span></div><div class="race-stage"><canvas id="raceCanvas"></canvas><div class="hud"><div class="hud-panel hud-pos" id="hudPos">P<span>—</span><small>ON THE GRID</small></div><div class="hud-panel hud-timing" id="hudTiming">LAP 1 / 4<br>DRY TYRES<br>FUEL 100%</div><div class="hud-panel hud-gauge"><div><span class="speed" id="hudSpeed">000</span> <small>KM/H</small><span class="gear" id="hudGear">1</span></div><div class="tyres"><i class="tyre"></i><i class="tyre"></i><i class="tyre"></i><i class="tyre"></i></div><div style="font:9px 'DM Mono';margin-top:7px;color:#b1bbb6">TYRE LIFE <b id="hudWear">100%</b> · DAMAGE <b id="hudDamage">0%</b></div></div><div class="hud-message" id="hudMessage">LIGHTS OUT</div><div class="touch-controls"><div class="touch-group"><button data-key="ArrowLeft">◀</button><button data-key="ArrowRight">▶</button></div><div class="touch-group"><button data-key="ArrowDown">BRAKE</button><button data-key="ArrowUp">GO</button></div></div></div></div><div class="race-bottom"><span id="raceStatus">ARROWS DRIVE · SPACE HANDBRAKE · C VIEW</span><div class="controls"><button class="btn ghost" id="pauseRace" style="padding:7px 12px">PAUSE</button><button class="btn ghost" id="quitRace" style="padding:7px 12px">RETIRE</button></div><span>4-LAP SPRINT · ${raceData.weather}</span></div></div>`;let canvas=$('#raceCanvas');canvas.width=innerWidth*devicePixelRatio;canvas.height=(innerHeight-100)*devicePixelRatio;let ctx=canvas.getContext('2d');raceData.canvas=canvas;raceData.ctx=ctx;document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();raceData.keys[b.dataset.key]=true};b.onpointerup=b.onpointerleave=()=>raceData.keys[b.dataset.key]=false});$('#viewToggle').onclick=()=>{raceData.view=raceData.view==='chase'?'cockpit':'chase';$('#viewToggle').textContent='C';$('#viewToggle').parentElement.firstChild.textContent=raceData.view.toUpperCase()+' VIEW '};$('#pauseRace').onclick=()=>{raceData.paused=!raceData.paused;$('#pauseRace').textContent=raceData.paused?'RESUME':'PAUSE';$('#raceStatus').textContent=raceData.paused?'PAUSED · CLICK RESUME TO CONTINUE':'ARROWS DRIVE · SPACE HANDBRAKE · C VIEW'};$('#quitRace').onclick=()=>finishRace(true);window.onresize=()=>{if(raceData?.canvas){raceData.canvas.width=innerWidth*devicePixelRatio;raceData.canvas.height=(innerHeight-100)*devicePixelRatio}}}
function raceFrame(now){if(!raceData||state.view!=='race'||raceData.done)return;let r=raceData,dt=Math.min(.05,(now-r.last)/1000);r.last=now;if(!r.paused){r.time+=dt;let k=r.keys,car=TEAMS[state.player.team].car,wet=r.weather==='RAIN';if(k.ArrowUp)r.speed+=dt*(car.accel*.36+27);else r.speed-=dt*18;if(k.ArrowDown)r.speed-=dt*75;if(k[' '])r.speed-=dt*45;r.speed=clamp(r.speed,0,320);r.steer+=(Number(!!k.ArrowRight)-Number(!!k.ArrowLeft))*dt*2.7;r.steer*=Math.pow(.91,dt*60);if(Math.abs(r.steer)>1.05)r.offTrack+=dt;else r.offTrack=Math.max(0,r.offTrack-dt*.8);if(r.offTrack>.3){r.speed=Math.max(55,r.speed-dt*42);if(r.offTrack>1.3){r.damage=clamp(r.damage+dt*2,0,100);r.offTrack=0;r.message='OFF TRACK';r.messageTime=.8}}if(Math.abs(r.steer)>1.8){r.collisions++;r.damage=clamp(r.damage+7,0,100);r.steer*=.4;r.message='CONTACT';r.messageTime=.8}r.wear=clamp(r.wear+dt*(.11+(r.speed/320)*.09+(wet?.04:0)),0,100);r.fuel=clamp(r.fuel-dt*.095,0,100);let lapDist=TRACKS[state.round%12][2],scale=10*(1-r.wear*.003-r.damage*.004-(wet?.07:0));r.distance+=r.speed/3600*scale*dt;if(r.distance>=lapDist*4){r.distance=lapDist*4;finishRace(false);return}r.lap=Math.min(4,Math.floor(r.distance/lapDist)+1);if(r.messageTime>0)r.messageTime-=dt;else r.message='';}drawRace();updateHud();requestAnimationFrame(raceFrame)}
function drawRace(){let r=raceData,c=r.ctx,w=r.canvas.width,h=r.canvas.height,dpr=devicePixelRatio,progress=r.distance/(TRACKS[state.round%12][2]*4),steer=r.steer;c.save();c.scale(dpr,dpr);w/=dpr;h/=dpr;let sky=c.createLinearGradient(0,0,0,h*.6);sky.addColorStop(0,r.weather==='RAIN'?'#718b8a':'#5d8195');sky.addColorStop(1,'#c7c28e');c.fillStyle=sky;c.fillRect(0,0,w,h);c.fillStyle='#445747';c.fillRect(0,h*.48,w,h*.52);c.fillStyle='#78876a';c.fillRect(0,h*.48,w,h*.11);let horizon=h*.43,curve=Math.sin(progress*55+performance.now()/2600)*w*.12+steer*w*.1,roadW=Math.min(w*.92, w*.19+(h-horizon)*.85),center=w/2+curve;c.fillStyle='#d9d4b8';c.beginPath();c.moveTo(center-roadW*.59,h);c.lineTo(center-roadW*.19,horizon);c.lineTo(center+roadW*.19,horizon);c.lineTo(center+roadW*.59,h);c.closePath();c.fill();c.fillStyle='#343b3c';c.beginPath();c.moveTo(center-roadW*.52,h);c.lineTo(center-roadW*.17,horizon);c.lineTo(center+roadW*.17,horizon);c.lineTo(center+roadW*.52,h);c.closePath();c.fill();for(let i=0;i<14;i++){let z=((i/14+progress*4)%1),y=horizon+(h-horizon)*z*z,x=center+(w/2-center)*z*z,ww=roadW*(.18+.34*z*z);c.fillStyle=i%2?'#e7e2cf':'#ce5148';c.fillRect(x-ww,y,ww*.16,Math.max(1,2+z*13));c.fillRect(x+ww*.84,y,ww*.16,Math.max(1,2+z*13))}for(let i=0;i<8;i++){let y=horizon+(h-horizon)*Math.pow((i+1)/9,2),z=(y-horizon)/(h-horizon);c.fillStyle='#f0e9ce';c.fillRect(center-roadW*(.17+.35*z),y,roadW*(.34+.7*z),Math.max(1,z*3))}if(r.weather!=='CLEAR'){c.fillStyle='#ffffff18';for(let i=0;i<90;i++){let x=(i*173+performance.now()*.18)%w,y=(i*97+performance.now()*.42)%h;c.fillRect(x,y,1,7)}}if(r.view==='chase'){let x=w/2+steer*w*.08,y=h*.79;c.fillStyle='#171d1e';c.fillRect(x-w*.085,y+h*.035,w*.17,h*.045);c.fillStyle=TEAMS[state.player.team].color;c.beginPath();c.moveTo(x-w*.07,y);c.lineTo(x-w*.04,y-h*.09);c.lineTo(x+w*.04,y-h*.09);c.lineTo(x+w*.07,y);c.closePath();c.fill();c.fillRect(x-w*.11,y-h*.01,w*.22,h*.025);c.fillStyle='#f1edcf';c.fillRect(x-w*.04,y-h*.085,w*.08,h*.017);c.fillStyle='#111';c.fillRect(x-w*.055,y-h*.12,w*.11,h*.015)}else{c.fillStyle='#151b1c';c.fillRect(0,h*.78,w,h*.22);c.fillStyle='#879e96';c.fillRect(w*.35,h*.63,w*.3,h*.17);c.fillStyle='#202a2a';c.fillRect(w*.43,h*.68,w*.14,h*.09);c.fillStyle='#aab8a5';c.fillRect(w*.47,h*.69,w*.06,h*.045)}c.restore()}
function updateHud(){let r=raceData,p=state.player,t=TRACKS[state.round%12],wear=100-Math.round(r.wear),tyres=document.querySelectorAll('.tyre');$('#hudSpeed').textContent=String(Math.round(r.speed)).padStart(3,'0');$('#hudGear').textContent=String(Math.min(7,Math.floor(r.speed/42)+1));$('#hudTiming').innerHTML=`LAP ${r.lap} / 4<br>${r.weather==='RAIN'?'WET':'DRY'} TYRES<br>FUEL ${Math.round(r.fuel)}%`;$('#hudWear').textContent=wear+'%';$('#hudDamage').textContent=Math.round(r.damage)+'%';tyres.forEach((x,i)=>{x.className='tyre'+(wear<65?' worn':'')+(wear<30?' bad':'')});$('#hudMessage').textContent=r.message;$('#hudMessage').style.display=r.message?'block':'none';$('#raceClock').textContent=`${Math.floor(r.time/60)}:${String(Math.floor(r.time%60)).padStart(2,'0')}.${Math.floor(r.time%1*10)}`;$('#hudPos').innerHTML=`P<span>—</span><small>LIVE POSITION</small>`}
const POINTS=[25,18,15,12,10,8,6,4,2,1];
function finishRace(retired){let r=raceData;if(!r||r.done)return;r.done=true;r.retired=retired;let list=state.drivers.filter(d=>d!==state.player).map(d=>{let car=TEAMS[d.team].car,score=d.rating*.48+car.speed*.12+car.corner*.15+car.reliability*.08+d.attrs.consistency*.08+rnd(-15,15);return{d,score}});let car=TEAMS[state.player.team].car;let playerScore=state.player.rating*.48+car.speed*.12+car.corner*.15+car.reliability*.08+state.player.attrs.consistency*.08+(100-r.wear)*.08-r.damage*.17-(retired?100:0)+rnd(-8,8);list.push({d:state.player,score:playerScore});list.sort((a,b)=>b.score-a.score);let position=list.findIndex(x=>x.d===state.player)+1,points=retired?0:(POINTS[position-1]||0);if(position===1&&!retired)state.player.wins++;if(position<=3&&!retired)state.player.podiums++;state.player.points+=points;state.player.rep=clamp((state.player.rep||18)+(position<=3?7:position<=10?3:-2),0,100);state.player.races=(state.player.races||0)+1;state.player.experience=state.player.races;state.drivers.forEach(d=>{if(d!==state.player){let s=list.find(x=>x.d===d);let pos=list.findIndex(x=>x.d===d)+1;d.points+=POINTS[pos-1]||0;if(pos===1)d.wins++;if(pos<=3)d.podiums++}});let result={track:TRACKS[state.round%12][0],position,points,weather:r.weather,time:r.time,retired,wear:Math.round(r.wear),damage:Math.round(r.damage)};state.history.push(result);state.lastResult=result;save();renderResults(list,result)}
