n></div>`;$('#continue').onclick=advanceCareer}
function advanceCareer(){state.round++;if(state.round>=12){state.round=0;finishSeason()}state.view='home';delete state.lastResult;save();render()}
function finishSeason(){let p=state.player;p.age++;p.experience=(p.experience||0)+1;p.rep=clamp((p.rep||18)+Math.round((p.points-60)/15),0,100);let offers=TEAMS.map((t,i)=>({team:i,fit:clamp(Math.round(26+(p.rep-35)*.65+(Object.values(t.car).slice(0,6).reduce((a,b)=>a+b,0)/6-70)*.45+rnd(-10,10)),5,98)})).sort((a,b)=>b.fit-a.fit).slice(0,4);state.season++;state.round=0;state.drivers.forEach(d=>{if(d!==p){d.age++;if(d.age>39&&rnd(1,100)<28){d.age=21;d.name=NAMES[rnd(0,NAMES.length-1)]+' '+['Jr.','II',''][rnd(0,2)];d.rating=clamp(d.rating+rnd(-4,3),55,88);d.attrs={};ATTRS.forEach(a=>d.attrs[a]=clamp(d.rating+rnd(-14,13),22,98));d.points=0;d.wins=0;d.podiums=0}}d.points=0});p.points=0;state.drivers=state.drivers.slice(0,20);state.offers=offers;state.endSeason=true;save();setTimeout(()=>seasonOffers(),80)}
function seasonOffers(){let p=state.player,offers=state.offers||[],cards=offers.map(o=>{let t=TEAMS[o.team];return `<div class="contract-card"><div class="teamstripe" style="background:${t.color}"></div><div class="eyebrow">${o.team===p.team?'RENEWAL OFFER':'CONTRACT OFFER'} · FIT ${o.fit}%</div><h3>${t.name}</h3><p>${o.team===p.team?'Your current team wants you back.':'A new garage is interested in your services.'}</p><button class="btn season-sign" data-team="${o.team}" style="width:100%;background:${t.color}">${o.team===p.team?'RENEW CONTRACT':'MOVE TEAM'} →</button></div>`}).join('');modal(`Season ${state.season-1} complete`, `<p style="color:#aab5b0">You are now ${p.age}. Your reputation is ${p.rep}/100. Choose where to race next season.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px">${cards}</div>`);document.querySelectorAll('.season-sign').forEach(b=>b.onclick=()=>{let team=+b.dataset.team;if(team!==p.team){let newmate=state.drivers.find(d=>d.team===team);let oldmate=state.drivers.find(d=>d.team===p.team&&d!==p);if(newmate){newmate.team=p.team;oldmate.team=team}p.team=team}state.endSeason=false;delete state.offers;save();document.querySelector('.modal-back')?.remove();render()})}
