8: function makeDrivers(){let all=[];TEAMS.forEach((t,ti)=>{for(let j=0;j<2;j++){let base=ti===2?83:ti===1?79:ti===9?65:rnd(68,79),d={name:NAMES[ti*2+j],team:ti,age:rnd(21,36),rating:base,experience:rnd(0,8),points:0,wins:0,podiums:0,retired:false,attrs:{}};ATTRS.forEach(a=>d.attrs[a]=clamp(base+rnd(-14,13),22,98));all.push(d)}});return all}function fresh(){return{season:2001,round:0,player:null,drivers:makeDrivers(),history:[],view:'home'}}let state;try{state=JSON.parse(localStorage.getItem('gridline-save'))||fresh()}catch(e){state=fresh()}if(!state.drivers||state.drivers.length<20)state=fresh();function save(){localStorage.setItem('gridline-save',JSON.stringify(state))}const $=s=>document.querySelector(s);
