12: function careerPage(){let p=state.player,t=TEAMS[p.team],track=TRACKS[state.round%12],ordered=[...state.drivers].sort((a,b)=>b.points-a.points),mate=state.drivers.find(d=>d.team===p.team&&d!==p);return `<div class="hero"><div><div class="eyebrow">${t.name} · Season ${state.season} · Round ${state.round+1} of 12</div><h1>Make some<br><em>noise, ${esc(p.name.split(' ')[0])}.</em></h1><div class="subline">${state.history.length?`Last time out: ${state.history.at(-1).track} · P${state.history.at(-1).position}`:'Your first Grand Prix is just around the corner.'}</div></div><div class="pill">${t.name.toUpperCase()} / #${String(27+p.team).padStart(2,'0')}</div></div><div class="layout"><section><div class="panel"><div class="panel-head"><div class="panel-title">Next event</div><span class="eyebrow">ROUND ${String(state.round+1).padStart(2,'0')} / 12</span></div><div class="panel-body"><div class="track-card"><div class="track-name">${track[0]}</div><div class="track-meta" style="position:absolute;left:22px;top:55px">${track[1].toUpperCase()} · ${track[2]} KM</div><svg class="track-svg" viewBox="0 0 300 210"><path d="M42 133 C15 115 45 64 80 70 C105 74 105 107 135 107 C168 107 166 48 203 44 C242 40 270 81 246 105 C222 130 183 113 180 147 C177 178 230 180 255 155 C273 138 263 112 248 105"/><path class="inside" d="M42 133 C15 115 45 64 80 70 C105 74 105 107 135 107 C168 107 166 48 203 44 C242 40 270 81 246 105 C222 130 183 113 180 147 C177 178 230 180 255 155 C273 138 263 112 248 105"/></svg><div class="event-info"><div class="event-number">${String(state.round+1).padStart(2,'0')}</div><div class="weather">${track[4]}<br>${track[3]} LAPS · ${rnd(18,30)}°C<br>FORECAST: ${state.round%5===4?'LIGHT RAIN':state.round%7===2?'CHANGEABLE':'CLEAR'}</div></div></div><div class="stats-row"><div class="statbox"><label>Championship</label><strong>#${ordered.findIndex(d=>d===p)+1}</strong><span>${p.points} points</span></div><div class="statbox"><label>Wins</label><strong>${p.wins}</strong... (line truncated to 2000 chars)
13: function render(){if(state.view==='race'){renderRace();return}let app=$('#app');app.innerHTML=`<header class="topbar"><div class="brand"><i class="brandmark"></i><span>GRIDLINE <small>2001 / WORLD CHAMPIONSHIP</small></span></div><div class="topright"><span class="optional">${state.player?esc(state.player.name.toUpperCase()):'ROOKIE DRIVER'}</span><span class="season-tag">SEASON ${state.season}</span></div></header><main class="wrap">${state.player?careerPage():homePage()}</main>`;bindMain()}
14: function modal(title,body){let old=document.querySelector('.modal-back');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="btn ghost close-modal" style="padding:7px 11px">CLOSE ×</button></div><div class="modal-content">${body}</div></div></div>`);document.querySelector('.close-modal').onclick=()=>document.querySelector('.modal-back')?.remove();document.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))e.currentTarget.remove()}}
15: function createModal(){modal('Build your driver',`<p style="color:#aab5b0;font-size:13px;line-height:1.6;margin-top:0">The paddock will assess your profile and decide which teams are ready to take a chance. You do not choose your starting team.</p><form id="driverForm" class="form"><label>DRIVER NAME</label><input id="driverName" maxlength="24" required placeholder="e.g. Alex Morgan" value=""><label>DRIVING STYLE</label><select id="style"><option value="balanced">Balanced — reliable all-rounder</option><option value="qualifier">One-lap specialist — qualifying pace</option><option value="racer">Racecraft — overtaking and defence</option><option value="wet">Rain ace — wet-weather confidence</option></select><button class="btn" style="margin-top:12px">SUBMIT YOUR PROFILE →</button></form>`);document.querySelector('#driverForm').onsubmit=e=>{e.preventDefault();let name=$('#driverName').value.trim();if(name.length<2)return;const style=$('#style').value;let biases={balanced:{},qualifier:{qualifying:10,pace:4,consistency:-2},racer:{overtaking:12,defending:8,aggression:6},wet:{wet:16,consistency:4}}[style];let attrs={};ATTRS.forEach(a=>attrs[a]=clamp(rnd(52,76)+(biases[a]||0),30,94));let rating=Math.round(Object.values(attrs).reduce((a,b)=>a+b,0)/ATTRS.length);state.prospect={name,age:rnd(20,25),rating,experience:0,points:0,wins:0,podiums:0,rep:18,attrs};showOffers()}}
16: function showOffers(){let d=state.prospect;let offers=TEAMS.map((t,i)=>{let average=Object.values(t.car).slice(0,6).reduce((a,b)=>a+b,0)/6;let fit=Math.round(clamp(23+(d.rating-65)*.7+(average-70)*.45+rnd(-14,14),8,96));return{team:i,fit}}).sort((a,b)=>b.fit-a.fit).slice(0,5);state.offers=offers;let cards=offers.map(o=>{let t=TEAMS[o.team];return `<div class="contract-card"><div class="teamstripe" style="background:${t.color}"></div><div class="eyebrow">${o.fit>=68?'RACE SEAT OFFER':o.fit>=45?'DEVELOPMENT CONTRACT':'LONG SHOT'}</div><h3>${t.name}</h3><div class="rating">TEAM FIT ${o.fit}% · CAR OVR ${Math.round(Object.values(t.car).slice(0,6).reduce((a,b)=>a+b,0)/6)}</div><p>${o.fit>=68?'They believe your talent can score points from the outset.':o.fit>=45?'A chance to prove yourself in a competitive midfield car.':'A tough team, but a strong season could change everything.'}</p><button class="btn sign-team" data-team="${o.team}" style="width:100%;background:${t.color};box-shadow:3px 3px 0 #111">SIGN CONTRACT →</button></div>`}).join('');modal('The teams have spoken',`<div class="driver-card" style="margin-bottom:16px"><div class="portrait">${initials(d.name)}</div><div><h3>${esc(d.name)}</h3><p>AGE ${d.age} · OVERALL ${d.rating} · ROOKIE</p></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px">${cards}</div>`);document.querySelectorAll('.sign-team').forEach(b=>b.onclick=()=>signTeam(+b.dataset.team))}
17: function signTeam(team){let d=state.prospect,drivers=state.drivers.filter(x=>x.team===team).sort((a,b)=>a.rating-b.rating),replaced=drivers[0];Object.assign(d,{team,rep:20});state.drivers=state.drivers.filter(x=>x!==replaced);state.drivers.push(d);replaced.team=-1;state.reserve=replaced;state.player=d;delete state.prospect;delete state.offers;state.view='home';document.querySelector('.modal-back')?.remove();save();render()}
18: function calendarModal(){modal('2001 Championship calendar',`<div class="race-table">${TRACKS.map((t,i)=>`<div class="track-row ${i===state.round?'current':''}"><div class="round">${String(i+1).padStart(2,'0')}</div><div><b>${t[0]}</b><div style="font:9px 'DM Mono';color:#93a09b;margin-top:3px">${t[1]} · ${t[4]}</div></div><div>${t[2]} KM</div><div>${t[3]} LAPS</div></div>`).join('')}</div>`)}
